func:
// 感測融合：收下所有 sga/+/+ 訊息，算出每區的校正後人數，檢查規則並發出告警
// 輸出 1 → sga/system/state（整店狀態，retain）  輸出 2 → sga/system/alert  輸出 3 → 下行指令（msg.topic 已設好）
const NODES = ['entry-01', 'zone-A', 'zone-B', 'zone-C', 'zone-D'];
const RADAR = { A: true, B: true, C: false, D: true };
const st = flow.get('sga') || {
  capacity: Number(env.get('STOREGA_CAPACITY')) || 40,
  threshold: Number(env.get('STOREGA_THRESHOLD')) || 14,
  gateMode: 'auto', k: 0.62, kAuto: true,
  entry: { in: 0, out: 0, occupancy: 0, queue: 0, checkout: 0, gate: true, temp: null, hum: null },
  zones: { A: {}, B: {}, C: {}, D: {} }, nodes: {}, cool: {}, lastState: 0
};
const [, id, kind] = String(msg.topic).split('/');
const p = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const now = Date.now();
const alerts = [];
const cmds = [];

function alert(key, level, title, detail, coolMs = 15 * 60 * 1000) {
  if (st.cool[key] && now - st.cool[key] < coolMs) return;
  st.cool[key] = now;
  alerts.push({ payload: { key, level, title, detail, ts: now, source: 'node-red' } });
}

if (NODES.includes(id)) {
  const n = st.nodes[id] || (st.nodes[id] = {});
  if (kind === 'cmd') {
    // 儀表板送給板子的指令也會經過這裡，用來同步 Node-RED 記得的設定
    if (p.action === 'capacity' && p.value >= 10 && p.value <= 80) st.capacity = Number(p.value);
    if (p.action === 'gate' && ['auto', 'open', 'closed'].includes(p.mode)) st.gateMode = p.mode;
    if (p.action === 'calibrate' && p.k > 0) { st.k = Number(p.k); }
    if (p.action === 'threshold' && p.value >= 4 && p.value <= 30) st.threshold = Number(p.value);
  } else if (kind === 'event' && p.type === 'auto_zero') {
    // 入口板子在打烊 30 分鐘後把剩下的人數歸零：紅外線今天少算了這麼多人的離場
    n.last = now;
    alert('autozero', 'info', '打烊後場內人數歸零', `紅外線今天少算了 ${p.was} 人的離場，已由入口節點修正。`, 0);
  } else if (kind === 'ack') {
    n.last = now;  // 指令回覆只代表板子還活著，內容給儀表板看
  } else if (p.online === false) {
    n.last = 0; // MQTT 遺言：板子斷線
  } else {
    n.last = now;
    if (p.rssi != null) n.rssi = p.rssi;
    if (p.ip) n.ip = p.ip;
    if (p.fw) n.fw = p.fw;
    if (kind === 'counter') {
      Object.assign(st.entry, p);
      if (['auto', 'open', 'closed'].includes(p.mode)) st.gateMode = p.mode;
      if (p.capacity >= 10) st.capacity = p.capacity;
    }
    const z = id.startsWith('zone-') ? st.zones[id.slice(-1)] : null;
    if (z && kind === 'wifi' && p.raw != null) z.raw = Number(p.raw);
    if (z && kind === 'radar') { z.presence = !!p.presence; z.moving = !!p.moving; }
  }
}

// 融合：雷達判斷無人 → 0；否則 Wi-Fi 原始數 × k
let sumRaw = 0, sumEst = 0;
for (const zid of Object.keys(st.zones)) {
  const z = st.zones[zid], node = st.nodes['zone-' + zid] || {};
  z.online = !!node.last && now - node.last < 15000;
  z.est = RADAR[zid] && z.presence === false ? 0 : Math.round((z.raw || 0) * st.k);
  if (z.online) { sumRaw += z.raw || 0; sumEst += z.est; }
}
st.sumRaw = sumRaw; st.sumEst = sumEst;

// 規則
const occ = Number(st.entry.occupancy) || 0, ratio = occ / st.capacity;
if (ratio >= 1) alert('cap100', 'crit', '已達人數上限，閘門關閉', `場內 ${occ} / ${st.capacity} 人，門外排隊 ${st.entry.queue || 0} 人。`, 5 * 60 * 1000);
else if (ratio >= 0.8) alert('cap80', 'warn', '場內人數接近上限', `目前 ${occ} / ${st.capacity} 人（${Math.round(ratio * 100)}%）。`);
for (const zid of Object.keys(st.zones)) {
  const z = st.zones[zid];
  if (z.online && z.est > st.threshold) alert('z-' + zid, 'warn', `${zid} 區擁擠`, `校正後估計 ${z.est} 人，門檻 ${st.threshold} 人。`);
}
if (st.entry.temp != null && st.entry.temp >= 30) alert('temp', 'warn', '入口溫度偏高', `DHT11 讀值 ${st.entry.temp}°C。`, 30 * 60 * 1000);

flow.set('sga', st);
node.status({ fill: ratio >= 1 ? 'red' : ratio >= 0.8 ? 'yellow' : 'green', shape: 'dot', text: `場內 ${occ}/${st.capacity} · k ${st.k.toFixed(2)}` });

// 狀態最多每秒送一次
let state = null;
if (now - st.lastState >= 1000) {
  st.lastState = now;
  state = { payload: {
    ts: now, occupancy: occ, capacity: st.capacity, queue: st.entry.queue || 0, gate: !!st.entry.gate, gateMode: st.gateMode,
    entries: st.entry.in || 0, checkouts: st.entry.checkout || 0, conversion: st.entry.in ? +(st.entry.checkout / st.entry.in).toFixed(3) : 0,
    temp: st.entry.temp, hum: st.entry.hum, k: +st.k.toFixed(3), threshold: st.threshold,
    zones: Object.fromEntries(Object.entries(st.zones).map(([zid, z]) => [zid, { raw: z.raw || 0, est: z.est, presence: z.presence ?? null, online: z.online }])),
    nodes: Object.fromEntries(NODES.map(nid => { const n = st.nodes[nid] || {}; return [nid, { online: !!n.last && now - n.last < 15000, rssi: n.rssi ?? null }]; }))
  } };
}
return [state, alerts.length ? alerts : null, cmds.length ? cmds : null];

// 心跳檢查（每 5 秒）：超過 15 秒沒有訊息就判定離線，恢復時再通知一次
const NODES = ['entry-01', 'zone-A', 'zone-B', 'zone-C', 'zone-D'];
const st = flow.get('sga');
if (!st) return null;
const now = Date.now(), out = [];
st.offline = st.offline || {};
for (const id of NODES) {
  const n = st.nodes[id] || {}, online = !!n.last && now - n.last < 15000;
  if (!online && !st.offline[id] && n.seen !== undefined) {
    st.offline[id] = now;
    out.push({ payload: { key: 'off-' + id, level: 'crit', title: `${id} 離線`, detail: '超過 15 秒沒有心跳，請檢查電源與 Wi-Fi。', ts: now, source: 'node-red' } });
  }
  if (online && st.offline[id]) {
    const sec = Math.round((now - st.offline[id]) / 1000);
    delete st.offline[id];
    out.push({ payload: { key: 'on-' + id, level: 'info', title: `${id} 恢復連線`, detail: `離線 ${sec} 秒，訊號 ${n.rssi} dBm。`, ts: now, source: 'node-red' } });
  }
  if (online) n.seen = true;
}
flow.set('sga', st);
const off = NODES.filter(id => st.offline[id]);
node.status(off.length ? { fill: 'red', shape: 'ring', text: '離線：' + off.join(', ') } : { fill: 'green', shape: 'dot', text: '5 / 5 在線' });
return [out.length ? out : null];

// 自動校正 k（每分鐘）：k = 0.7 × k + 0.3 × (入口人數 ÷ Wi-Fi 裝置總數)
// msg.payload === 'now' 時（手動按鈕）直接採用新值並通知入口節點
const st = flow.get('sga');
if (!st) return null;
const occ = Number(st.entry.occupancy) || 0;
if (!(st.sumRaw > 0) || occ <= 0) { node.status({ fill: 'grey', shape: 'ring', text: '等待資料' }); return null; }
const target = Math.min(1.2, Math.max(0.2, occ / st.sumRaw));
const manual = msg.payload === 'now';
if (!manual && !st.kAuto) return null;
const before = st.k;
st.k = manual ? target : 0.7 * st.k + 0.3 * target;
flow.set('sga', st);
node.status({ fill: 'blue', shape: 'dot', text: `k ${before.toFixed(2)} → ${st.k.toFixed(2)}` });
if (!manual) return null;
return { topic: 'sga/entry-01/cmd', payload: { action: 'calibrate', k: +st.k.toFixed(3) } };

// 整點紀錄：每小時把當下狀態寫成一行 CSV（接 file 節點，附加到 storega-log.csv）
const st = flow.get('sga');
if (!st) return null;
const d = new Date(), z = st.zones;
const line = [d.toISOString(), st.entry.in || 0, st.entry.out || 0, st.entry.occupancy || 0, st.entry.checkout || 0,
  st.k.toFixed(3), z.A.est ?? '', z.B.est ?? '', z.C.est ?? '', z.D.est ?? '', st.entry.temp ?? '', st.entry.hum ?? ''].join(',');
return { payload: line };

// 每日紀錄（每分鐘）：把今天的逐時進場與每 5 分鐘場內人數記在 Node-RED，換日時封存成一天的摘要
// 歷史（最多 30 天）存在 storega-history.json，並以 retain 發到 sga/system/history，任何一台電腦打開儀表板都看得到
// msg.history（部署時從檔案讀進來）會先載入
// 輸出 1 → sga/system/history（retain）  輸出 2 → 寫檔 storega-history.json
const pad = n => String(n).padStart(2, '0');
const dayKey = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
let hist = flow.get('sgaHistory') || [];
if (Array.isArray(msg.history)) {  // loaded from the file at deploy
  hist = msg.history.filter(x => x && x.date).slice(-30);
  flow.set('sgaHistory', hist);
  return [{ payload: { days: hist, ts: Date.now() } }, null];
}
const st = flow.get('sga');
if (!st) return null;
const now = msg.now ? new Date(msg.now) : new Date(), today = dayKey(now);
const e = st.entry || {}, inn = Number(e.in) || 0, co = Number(e.checkout) || 0;
let day = flow.get('sgaDay');
let out1 = null, out2 = null;
if (!day || day.date !== today) {
  if (day && day.entries > 0) {  // the day just ended: keep its summary
    const d = new Date(day.date + 'T12:00:00');
    hist = hist.filter(x => x.date !== day.date).concat([{ date: day.date, label: `${d.getMonth() + 1}/${d.getDate()}`, sub: '週' + '日一二三四五六'[d.getDay()],
      entries: day.entries, checkouts: day.checkouts, dwell: day.dwell, hourly: day.hourly, occ: day.occ, source: 'node-red' }]).slice(-30);
    flow.set('sgaHistory', hist);
    out1 = { payload: { days: hist, ts: Date.now() } };
    out2 = { payload: JSON.stringify(hist) };
  }
  day = { date: today, hourly: Array(12).fill(0), occ: Array(144).fill(null), lastIn: inn, entries: 0, checkouts: 0, dwell: 0 };
}
// entries into the hour they happened (a smaller counter means the board reset: start again from it)
const delta = inn >= day.lastIn ? inn - day.lastIn : inn;
day.lastIn = inn;
const h = now.getHours();
if (delta > 0 && h >= 10 && h < 22) day.hourly[h - 10] += delta;
const slot = Math.floor(((h - 10) * 60 + now.getMinutes()) / 5);
if (slot >= 0 && slot < 144) day.occ[slot] = Number(e.occupancy) || 0;
day.entries = inn; day.checkouts = co; day.dwell = e.dwell_avg ? +(e.dwell_avg / 60).toFixed(1) : 0;
flow.set('sgaDay', day);
node.status({ fill: 'green', shape: 'dot', text: `${today} 進場 ${inn} · 歷史 ${hist.length} 天` });
return [out1, out2];
